 for(const separator of [' — ',' · ',' / '])if(key.includes(separator))return key.split(separator).map(part=>t(part)).join(separator);
 if((m=key.match(/^(.+) · Enter to play$/)))return `${t(m[1])} · Enter로 시작`;
